exercises.solution:
function resourceMatches(pattern, resource) {
  if (pattern.endsWith('*')) return resource.startsWith(pattern.slice(0, -1));
  return pattern === resource;
}

function ruleMatches(rule, action, resource) {
  const actionOk = rule.actions.includes('*') || rule.actions.includes(action);
  return actionOk && rule.resources.some((pattern) => resourceMatches(pattern, resource));
}

export function decide(policies, action, resource) {
  const matching = policies.filter((rule) => ruleMatches(rule, action, resource));
  if (matching.some((rule) => rule.effect === 'deny')) return 'deny';
  if (matching.some((rule) => rule.effect === 'allow')) return 'allow';
  return 'implicit-deny';
}

