exercises.solution:
export function isTenantScoped(filter, tenantId) {
  if (filter.eq) return filter.eq[0] === 'tenantId' && filter.eq[1] === tenantId;
  if (filter.and) return filter.and.some((part) => isTenantScoped(part, tenantId));
  return filter.or.every((branch) => isTenantScoped(branch, tenantId));
}

export function withTenant(filter, tenantId) {
  return { and: [{ eq: ['tenantId', tenantId] }, filter] };
}

