exercises.solution:
export function sessionExpiresAt(createdAtSec, lastSeenAtSec, idleSec, absoluteSec) {
  return Math.min(lastSeenAtSec + idleSec, createdAtSec + absoluteSec);
}

export function isSessionLive(nowSec, createdAtSec, lastSeenAtSec, idleSec, absoluteSec) {
  return nowSec < sessionExpiresAt(createdAtSec, lastSeenAtSec, idleSec, absoluteSec);
}

export function storeWritesPerSec(requestsPerSec, activeSessions, touchAfterSec) {
  return Math.min(requestsPerSec, activeSessions / touchAfterSec);
}

