exercises.solution:
export function refreshesPerSec(activeSessions, accessTtlSec) {
  return activeSessions / accessTtlSec;
}

export function revokedTokenUsableSec(accessTtlSec, leewaySec) {
  return accessTtlSec + leewaySec;
}

export function denylistEntries(revocationsPerSec, accessTtlSec, leewaySec) {
  return revocationsPerSec * revokedTokenUsableSec(accessTtlSec, leewaySec);
}
